// src/pages/PatientDashboard.js
import React from "react";
import "./DashboardLayout.css";

const PatientDashboard = () => {
  return (
    <div className="dashboard-container">
      <aside className="sidebar">
        <div className="logo">MEDIVAULT PRO</div>
        <nav className="nav-links">
          <button className="nav-button active">Dashboard</button>
          <button className="nav-button">Appointments</button>
          <button className="nav-button">Prescriptions</button>
          <button className="nav-button">Reports</button>
        </nav>
      </aside>

      <main className="main-content">
        <header className="topbar">
          <div className="welcome">Welcome, Patient</div>
          <button className="logout-button">Logout</button>
        </header>
        <section className="dashboard-details">
          <h2>Your Patient Dashboard</h2>
          <p>View your medical records and appointments</p>
        </section>
      </main>
    </div>
  );
};

export default PatientDashboard;
